'use strict';
// Detailed help for every command: `help <command>`. Each entry: [usage, what it does, examples, see also]. Aliases are added automatically from the alias table.
const H = {
  look: ['look [thing]', 'Shows where you are: the room name, its description, the exits, things lying around, resources you can gather, people and monsters. With a name it examines a monster, item, NPC or player instead. `look bag` lists your bag of holding, `look phone` describes your 🍍Phone Pro Max, `read sign` reads a sign. `look ground` (or the name of the ground, such as `look grass`, `look dirt`, `look stone`, `look concrete` or `look metal`) describes what you are standing on. Moving shows the full room too, unless you turned on `brief`.', ['look', 'look fountain', 'look wolf'], ['brief', 'go', 'check']],
  go: ['go <direction>', 'Walks through an exit. You can also just type the direction: n, s, e, w, u, d, ne, nw, se, sw (or north, south, east, west, up, down, northeast, northwest, southeast, southwest) and in or out for doorways. `out` also leaves a room that has only one exit. You cannot leave while you are fighting: `flee` first. Several steps in one go: `speedwalk`; or click a room on the map.', ['go north', 'n', 'ne', 'in', 'out'], ['speedwalk', 'travel', 'flee', 'recall']],
  kill: ['kill <monster>', 'Attacks a monster in your room and starts a fight: each round both sides roll d6 dice (a 5 or 6 is a hit) and net hits add damage. Use `cast` for abilities, `push` to spend Luck, `flee` to run. With `autokill on`, typing `kill` by itself attacks the first monster in the room.', ['kill wolf', 'kill (with autokill on)'], ['autokill', 'cast', 'flee', 'autoflee', 'push']],
  autokill: ['autokill on | autokill off', 'A toggle. When it is on, typing just `kill` (or `k`) attacks the first monster in the room, so you do not have to type its name every time. When it is off, `kill` needs a target. The setting is saved with your character.', ['autokill on', 'kill', 'autokill off'], ['kill', 'autoflee']],
  flee: ['flee', 'Tries to break off the fight and run through a random exit. It can fail (about one time in three) and you stay in the fight. `autoflee on` does it for you at 30% health.', ['flee'], ['autoflee', 'kill', 'recall']],
  autoheal: ['autoheal [on|off]', 'When on, the moment your health drops to 40% or below you automatically eat or drink the best healing item from your pack or bag (the same choice as the heal button). If you have no healing items, nothing happens. It waits a moment between uses so it will not waste your whole stock. Saved with your character. Works alongside autoflee (which runs away at 30%).', ['autoheal', 'autoheal off'], ['autoflee', 'quaff', 'bag']],
  autoflee: ['autoflee on | autoflee off', 'When on, you automatically try to flee when your health falls to 30% or less during a fight. Saved with your character.', ['autoflee on'], ['flee', 'kill']],
  get: ['get <item> | get all', 'Picks things up from the floor. Loot from your kills goes straight into your bag of holding when the bag mode allows it. Your pack has a limited size; the bag holds much more.', ['get sword', 'get all'], ['drop', 'inventory', 'bag']],
  drop: ['drop <item>', 'Puts an item from your pack on the floor. Your bound tools and the bag of holding cannot be dropped or sold. Worn items must be removed first.', ['drop torch'], ['get', 'remove', 'sell']],
  inventory: ['inventory', 'Lists every equipment slot (weapon, head, body, shield, feet) with the item worn in it, then your pack with duplicates grouped, your credits and bag space. Items marked [kept] are protected from selling and salvaging.', ['inventory', 'eq'], ['check', 'wield', 'wear', 'keep', 'bag']],
  keep: ['keep <item> | keep', 'Marks an item so it is never sold (`sell`, `sell all`, `rsell`), salvaged (`salvage`, `salvage all`) or put up for auction. Works on pack items and on stacks in your bag. `keep` alone lists everything kept. Saved with your character.', ['keep carbon blade', 'keep'], ['unkeep', 'sell', 'salvage', 'inventory']],
  unkeep: ['unkeep <item> | unkeep all', 'Removes the keep mark so the item can be sold or salvaged again.', ['unkeep carbon blade', 'unkeep all'], ['keep']],
  brief: ['brief on | brief off', 'With brief on, moving through rooms leaves out only the long room description. You still see the room name, the exits, items on the floor, resources you can gather, and the NPCs and monsters in the room, so it is handy when you run around. `look` always shows the long description too. Saved with your character.', ['brief on', 'brief off'], ['look', 'speedwalk']],
  idea: ['idea <your idea>', 'Sends a suggestion to the developer. It is filed on GitHub in the ideas folder of the Multiverse repository as a markdown file, and an issue is opened and assigned to toastmd so it lands on their to-do list. At least 8 characters and up to 1500; you can send one every 30 seconds (8 an hour).', ['idea a fishing contest at the docks', 'idea more recipes for cooks'], ['bug', 'gossip']],
  bug: ['bug <what went wrong>', 'Reports a bug. It is filed on GitHub in the bugs folder as a markdown file (with your character, the room you were in and the last lines of text you saw) and an issue is opened and assigned to toastmd. Say what you were doing and what you expected. At least 8 characters; one every 30 seconds (8 an hour).', ['bug the heal button says I have nothing to eat but I have stims in my bag'], ['idea', 'help']],
  email: ['email <address> | email hide | email show | email clear', 'Adds an email address to your profile (you can also use the settings panel). Anyone who fingers you sees it unless you hide it.', ['email me@example.com', 'email hide'], ['finger']],
  finger: ['finger <name>', 'Shows a player\'s name, title, level, class, picture and email (if they set one and did not hide it). Works for players who are offline too (it shows when they were last seen). Clicking a name in the Who window does the same.', ['finger zeph'], ['who', 'email']],
  wield: ['wield <weapon>', 'Equips a weapon from your pack. You need the weapon\'s level. A new weapon replaces the old one, which goes back to your pack.', ['wield blade'], ['wear', 'remove', 'check', 'inventory']],
  wear: ['wear <armor>', 'Puts on a piece of armor from your pack. It goes in its own slot (head, body, shield or feet) and needs the item\'s level. Armor class adds to your defense.', ['wear helmet'], ['wield', 'remove', 'check', 'inventory']],
  remove: ['remove <item>', 'Takes off a worn or wielded item and puts it back in your pack.', ['remove helmet'], ['wear', 'wield']],
  quaff: ['quaff [item]', 'Uses a stim, potion, soda or meal from your pack. With no item named (`eat`, `quaff`, or the HEAL button) it picks the healing item that fits best: the smallest one that covers the health you are missing, or your biggest healer if none covers it. Potions kept in your bag are used too.', ['quaff stim', 'eat', 'eat burger'], ['inventory', 'pray', 'rest']],
  list: ['list', 'Shows what the shop in this room sells as a numbered list, each line ending with its cost (for example `1. Brawn implant Mk I (level 1) Credits: 2000`). Buy with `buy <number>` or `buy <name>`. You can also use it at some other counters.', ['list'], ['buy', 'sell', 'value']],
  buy: ['buy <number> | buy [amount] <item>', 'Buys from the shop in this room: `buy 3` buys item number 3 from `list`, `buy stim` buys by name, and `buy 3 stim` or `buy 3 2` buys several (an amount first, then the item name or its list number).', ['buy stim', 'buy 3 stim'], ['list', 'sell']],
  sell: ['sell <item> | sell all | sell materials', 'Sells to the shop in this room. `sell all` sells everything unworn and not kept (but never potions), including bag stacks; `sell materials` sells only gathered materials (the Salvage Exchange pays more). Legendary items sell at full value. Kept items are skipped.', ['sell blade', 'sell all', 'sell materials'], ['keep', 'rsell', 'value', 'salvage']],
  value: ['value <item>', 'Tells you what the shopkeeper here would pay for an item in your pack.', ['value blade'], ['sell', 'check']],
  tools: ['tools', 'Shows your gathering tools (pickaxe, sickle, rod, crowbar, cook set...) and their tier. Tools are bound to you, level up with use, and cannot be dropped or sold.', ['tools'], ['tradeskills', 'forage', 'mine']],
  bag: ['bag [list] | bag put <item> | bag get <item> | bag auto loot|overflow|off', 'Syntax: `bag` or `look bag` lists it; `bag get <item> [n|all]` or `get <item> from bag` takes things out; `bag get all` takes every item (not materials) that fits in your pack, `bag get gear` all weapons and armor, `bag get materials` the materials. Gathered materials do not count toward the bag capacity: carry as many as you like. With `bag auto loot`, everything a monster drops goes straight into the bag. Your bag of holding stores extra items (60 slots, +20 for each remort). `bag` lists it, `put` and `get` (or `take`) move items in and out, and `auto` sets whether kills put loot straight into the bag.', ['bag', 'bag put ore', 'bag get ore', 'bag auto overflow'], ['inventory', 'get', 'sell']],
  recall: ['recall', 'Returns you to Ashfall Square from almost anywhere (not while fighting).', ['recall'], ['travel', 'speedwalk']],
  runto: ['runto <room id>', 'Runs to a room you have already explored in the same area, one step at a time (a fight, a blocked exit or typing another command stops it). You normally do this by clicking a room on the map; hover a room to see its name.', ['runto town/market'], ['speedwalk', 'travel', 'recall']],
  smoke: ['smoke [item]', 'Lights a cigarillo and heals you (about 380 hit points). The bosses of the Old West (Red Jack in the Redrock Trail, the Delver King, Dalton, the Brimstone Express and the Dry Gulch Bank manager) sometimes drop them. Not used by the heal button.', ['smoke'], ['quaff', 'inventory']],
  upgrade: ['upgrade [weapon] [confirm]', 'Upgrades a weapon at a forge (Brann\'s Smithy in Ashfall Square): +1 to +10, each upgrade adding damage in proportion to the weapon\'s level. It costs a lot of credits and each upgrade costs 1.75 times the last. `upgrade` previews the wielded weapon, `upgrade confirm` buys it, and `upgrade <weapon> confirm` upgrades one from your pack. Shops pay back 35% of what you spent on upgrades when you sell.', ['upgrade', 'upgrade confirm', 'upgrade blade confirm'], ['check', 'inventory', 'smith']],
  enter: ['enter <thing>', 'Steps into a portal or doorway object in the room, for example the mysterious portal at the Mirage Gate in the Sunscorch Dunes, which leads to the Primeval Rift full of dinosaurs.', ['enter portal'], ['go']],
  travel: ['travel <place>', 'Walks you to a landmark through safe rooms only, such as the guild, smithy, market, armory, temple, saloon, clinic or the gate. Type `travel` for the list.', ['travel guild', 'travel smithy'], ['speedwalk', 'recall']],
  speedwalk: ['speedwalk n,n,e,e,d', 'Walks a whole route one step at a time. Directions are n s e w u d ne nw se sw in out; counts work (3n); up to 60 steps. It stops if you cannot go that way or a fight starts; typing another command, or `speedwalk stop`, cancels it. The Directions page of the guide has ready-made routes.', ['speedwalk 5e,s,u', 'speedwalk stop'], ['travel', 'recall', 'go']],
  tradeskills: ['tradeskills [skill]', 'Lists your tradeskills (gathering and crafting) with levels, or shows details and recipes for one skill.', ['tradeskills', 'tradeskills smithing'], ['learn', 'tools', 'craft']],
  learn: ['learn <skill>', 'Learns a tradeskill. It is free and you can learn any of them at any time.', ['learn mining'], ['unlearn', 'tradeskills']],
  unlearn: ['unlearn <skill>', 'Forgets a tradeskill you learned.', ['unlearn fishing'], ['learn', 'tradeskills']],
  forage: ['forage', 'Gathers herbs where the room has them. Needs the Foraging skill; your sickle tier improves the yield.', ['forage'], ['mine', 'fish', 'tradeskills']],
  mine: ['mine', 'Digs ore where the room has it. Needs the Mining skill and uses your pickaxe.', ['mine'], ['forage', 'fish', 'smith']],
  fish: ['fish', 'Catches fish in rooms with water. Needs the Fishing skill and uses your rod.', ['fish'], ['cook', 'mine', 'forage']],
  smith: ['smith <recipe>', 'Forges weapons and armor from ore at a forge (Brann\'s Smithy and some other rooms). Type `smith` alone for the recipe list.', ['smith', 'smith iron sword'], ['mine', 'salvage', 'tradeskills']],
  brew: ['brew <recipe>', 'Brews potions from herbs. Type `brew` for the recipe list.', ['brew'], ['forage', 'quaff']],
  cook: ['cook <recipe>', 'Cooks meals from fish and ingredients at a hearth or camp. Meals heal more than plain rations.', ['cook'], ['fish', 'quaff']],
  craft: ['craft <recipe>', 'The Prospector\'s own crafting skill: combines gathered materials into useful things. Type `craft` alone for recipes.', ['craft'], ['tradeskills']],
  salvage: ['salvage <item> | salvage all', 'Breaks an unworn weapon or armor down into materials. `salvage all` breaks down everything in your pack and bag that is not worn, not marked `keep` and not legendary. Your salvaging skill and crowbar improve the yield.', ['salvage blade', 'salvage all'], ['keep', 'smith', 'sell']],
  pray: ['pray', 'Heals you at a temple or clinic. It is free until level 15, then it costs credits.', ['pray'], ['rest', 'quaff']],
  rest: ['rest', 'Heals you fully at an inn or camp (a saloon bed, a safe camp). It costs a little at some places.', ['rest'], ['pray', 'quaff']],
  talk: ['talk <person>', 'Speaks to an NPC in the room. They greet you, hand in any finished contract, and a pop-up window lists everything they can give you with an Accept button on each quest (and an Accept all button), so you do not have to type accept. Use the name or part of it.', ['talk torv'], ['accept', 'quests', 'board']],
  accept: ['accept <quest>', 'Takes a contract the NPC in the room offers, by quest id or by the start of its name. You normally just click Accept in the pop-up that `talk` and `board` open. Accepted quests show in the quest window.', ['accept first'], ['talk', 'quests', 'abandon']],
  quests: ['quests', 'It opens the Quest log window, with a Current tab (what each quest still needs) and a Completed tab. Lists your accepted contracts and what each needs. The Quests button or the Q key shows the quest window.', ['quests'], ['accept', 'abandon', 'board']],
  board: ['board', 'Reads the contract board at the Adventurers\' Guild: the open contracts for your level with their rewards, as text and as a pop-up (Accept works for quests whose giver is in the room).', ['board'], ['talk', 'accept', 'quests']],
  abandon: ['abandon <quest>', 'Drops an accepted contract (your progress on it is lost).', ['abandon first steps'], ['quests', 'accept']],
  gossip: ['gossip <text> | gossip on | gossip off | gossip history', 'Speaks on the global channel everyone hears (also `/g text`). Add `;word` for a GIF, or paste a YouTube link for a thumbnail. `gossip off` hides the channel for you.', ['gossip hello all', '/g anyone want to team up?', 'gossip ;dance'], ['say', 'shout', 'tell', 'mute']],
  say: ['say <text>', 'Talks to everyone in your room.', ['say hello'], ['tell', 'shout', 'gossip']],
  tell: ['tell <player> <text>', 'Sends a private message to one player who is online.', ['tell rook want to team up?'], ['say', 'gossip']],
  shout: ['shout <text>', 'Shouts a message that every player online hears, wherever they are.', ['shout the boss is up!'], ['say', 'gossip']],
  who: ['who', 'Opens the Who window: everyone online with portrait, pre-title, name, title, class, level and gender (click a card to finger that player), and prints a line per player.', ['who'], ['finger', 'tell']],
  leaderboard: ['leaderboard', 'The top 10 achievements window: level, quests, tradeskills, bounty points and exploration points (x5 each) combine into a score (a remort is worth 40 levels). The L key opens it too.', ['top'], ['bounties', 'score']],
  team: ['team invite <player> | accept | decline | leave | kick <player> | lead <player> | list', 'Teams of up to five share experience and credits from kills (with a bonus for each extra member in the same room). `team invite` asks a player to join; the invited player gets a pop-up with Accept and Decline buttons (or types `team accept` or `team decline` within 90 seconds), `lead` passes leadership, `kick` removes someone.', ['team invite zeph', 'team accept', 'team leave'], ['tc', 'who']],
  tc: ['tc <text>', 'Team chat: talks to everyone on your team wherever they are.', ['tc pulling the boss now'], ['team']],
  bounties: ['bounties', 'Shows the wanted list (a new bounty every 15 minutes, up to 3 at a time, each lasting 40 minutes) and your bounty points. Kill the target for points and a reward; bounty points count toward the leaderboard.', ['bounties'], ['leaderboard', 'kill']],
  rob: ['rob <person>', 'Holds up a stationary NPC in the Dry Gulch Bank for credits. Part of the Bank Robbery contract; guards react.', ['rob teller'], ['unlock', 'loot']],
  unlock: ['unlock vault', 'Uses the Bank Manager\'s vault key to open the Dry Gulch Bank vault. It locks again after five minutes.', ['unlock vault'], ['rob', 'loot']],
  loot: ['loot vault', 'Takes the credits from an open bank vault (3,500 to 9,500).', ['loot vault'], ['unlock', 'rob']],
  rsell: ['rsell [healing|all] [list]', 'Sells all your unworn, non-legendary weapons and armor, and your gathered materials (ore, herbs, fish and so on), from the pack and bag, from anywhere, for 90% of the shop price (materials sell at the normal 40% rate, since the 60% rate needs the Salvage Exchange). `rsell list` previews it. Kept items are skipped.  `rsell healing` sells only your healing items (potions, food and drink) and `rsell all` sells everything at once. Kept items are never sold.', ['rsell list', 'rsell'], ['keep', 'sell', 'salvage']],
  auction: ['auction <item> [opening bid]', 'Puts equipment or treasure up for auction to the whole MUD from anywhere. Bids go up in steps of 100 and the funds are held; the hammer falls after "going once, going twice". Kept items cannot be auctioned.', ['auction blade 500'], ['bid', 'auctions', 'keep']],
  bid: ['bid [amount]', 'Bids on the running auction. With no amount it raises by one step (100).', ['bid', 'bid 900'], ['auction', 'auctions']],
  auctions: ['auctions', 'Shows the running auction and the queue.', ['auctions'], ['auction', 'bid']],
  blackjack: ['blackjack | hit | stand', 'Plays cards at any saloon for 1,000 credits a game. Win pays 1:1, blackjack 3:2, a push returns your stake; the dealer stands on 17. Type `hit` for another card and `stand` to hold. `blackjack off` leaves the table.', ['blackjack', 'hit', 'stand'], ['score']],
  cast: ['<ability> [target]  (or cast <ability> [target])', 'Uses a class ability. Every ability is a ONE-WORD command (no underscores): just type the word, for example `fireball`, `rage` or `song`, optionally followed by a target (`fireball wolf`). `spells` lists your abilities with their words; `help <word>` explains one. Abilities cost mana (stamina for Prospectors), and some have cooldowns.', ['fireball wolf', 'rage', 'cast heal'], ['spells', 'kill']],
  spells: ['spells', 'Lists your class abilities with the level that unlocks them and their mana cost, plus tradeskill hints. The ability grid on the left is clickable.', ['spells'], ['cast', 'class']],
  class: ['class', 'Describes your class, its strengths and your abilities.', ['class'], ['spells', 'remort', 'score']],
  luck: ['luck', 'Shows your Luck points. Luck refills at the clinic and when you level.', ['luck'], ['push']],
  push: ['push', 'Spends one Luck point for extra attack dice on your next rounds in a fight.', ['push'], ['luck', 'kill']],
  score: ['score | score text', 'Opens a graphical character sheet: portrait, XP bar, health, mana, aura, luck, an attribute radar chart, attack and defense dice, equipment, wealth, quest progress, pack and bag, tradeskills, chrome and materials. `score text` prints the text version. Esc closes the window.', ['score', 'score text'], ['class', 'inventory', 'leaderboard']],
  check: ['check <item>', 'Examines a weapon or armor and tells you its weapon class (damage range and average) or armor class, the slot, the level you need and how it compares with what you have on. Anything else answers "This isn\'t a piece of equipment." Works on items in your pack, worn, in your bag or on the floor.', ['check blade', 'check helmet'], ['inventory', 'wield', 'wear', 'value']],
  remort: ['remort', 'The level cap is 200. At level 200, in the Hall of Rebirth, `remort` resets you to level 1 as a more powerful remort class (Dragon, Android, Shapeshifter, Gambler, Ripperdoc, Outlaw or Pirate). Your gear stays in your pack and your bag grows.', ['remort', 'remort confirm pirate'], ['class', 'score']],
  cyber: ['cyber', 'Shows the chrome (cyberware) you have installed. Implants are bought at the clinic and implant lab.', ['cyber'], ['install', 'uninstall']],
  install: ['install <number|implant>', 'Installs a piece of cyberware at the implant lab: `install 3` uses the number from `list`, or give the name. Each implant adds an edge and uses a slot.', ['install reflex'], ['uninstall', 'cyber']],
  uninstall: ['uninstall <implant>', 'Removes an installed implant.', ['uninstall reflex'], ['install', 'cyber']],
  notify: ['notify on | notify off', 'Turns login and logout notices on or off for you.', ['notify off'], ['mute']],
  mute: ['mute [bounties|levels|quests|weather|taunts|deaths] [on|off]', 'Hides a kind of announcement: bounty announcements, level-ups of other players, quest completions, weather events (messages, animation and sounds), the **taunts** channel (what NPCs shout at players who die) or the **deaths** channel (a line for every death). `mute taunts on` hides taunts and `mute taunts off` shows them again; the same words work for the others. `mute` alone lists the settings, and they are also checkboxes in settings.', ['mute taunts on', 'mute deaths on', 'mute weather off'], ['notify', 'weather', 'deaths']],
  weather: ['weather', 'Tells you the weather in your area. Old West areas get rain, dust devils and tornadoes; the Modern district rain and snow; sci-fi areas electrical storms and electromagnetic pulses. Weather never hurts you. Wizards can start one with `weather <kind>` or `weather clear`.', ['weather'], ['mute']],
  deaths: ['deaths [number] | deaths <player> | deaths top', 'The death tally: recent player deaths with date, time, player and the NPC that killed them, and the deadliest NPCs. A number shows more rows, a name filters by player, `top` shows only the ranking. (Every death is also announced as it happens on the deaths channel; `mute deaths on` hides that channel.)', ['deaths', 'deaths 30', 'deaths joe', 'deaths top'], ['who', 'mute']],
  title: ['title <text> | title clear', 'Sets your own title (up to 40 characters) shown after your name in the Who window.', ['title the Unlucky'], ['who', 'finger']],
  gender: ['gender male | female | other', 'Changes your gender, which only changes your portrait and how you are described.', ['gender other'], ['who', 'class']],
  gag: ['gag on | gag off', 'Hides the misses and fumbles from the combat text so fights are shorter to read.', ['gag on'], ['kill']],
  socials: ['socials', 'Lists the feelings you can act out, like smile, cheer, dance or wave. Type one alone, or aim it: `wave rook`.', ['socials', 'dance', 'wave zeph'], ['say', 'gossip']],
  triggers: ['triggers', 'Lists your triggers: automatic reactions to text that appears in the game. Also available in settings.', ['triggers'], ['trigger']],
  trigger: ['trigger add <text> => <command> | trigger del <number> | trigger on <number> | trigger off <number>', 'Makes the game run a command, or highlight a line, whenever matching text appears. The text can be a plain phrase or a /regex/. A cooldown prevents loops; you can have up to 30.', ['trigger add The wolf bites => flee', 'trigger del 1'], ['triggers', 'alias']],
  alias: ['alias <name> <commands> | alias', 'Creates a shortcut. Separate several commands with ;. `alias` alone lists yours (up to 50). Saved with your character.', ['alias aa kill wolf;cast fireball', 'alias'], ['unalias', 'trigger']],
  unalias: ['unalias <name>', 'Deletes one of your aliases.', ['unalias aa'], ['alias']],
  keypad: ['keypad [on|off]', 'Keypad controls are ON by default (with Num Lock on and the command line empty, 1 southwest, 2 south, 3 southeast, 4 west, 5 look, 6 east, 7 northwest, 8 north, 9 northeast, 0 get all, . heal, + down, - up, * out, / kill). `keypad` shows the 16 shortcuts, which you can edit in settings; `keypad off` turns them off, and your choice is saved with your character.', ['keypad'], ['alias']],
  tutorial: ['tutorial', 'Opens the newbie tutorial window again. Finishing it for the first time completes the Welcome to the Multiverse quest.', ['tutorial'], ['help', 'commands']],
  commands: ['commands [category | word]', 'Lists every command you can use by category, and your class abilities. Add a category (for example `commands social`) for one line of description each, or a word to search.', ['commands', 'commands combat', 'commands walk'], ['help']],
  help: ['help [command]', 'Shows help. `help <command>` gives detailed help for any command (aliases work too, such as `help eq`), and `help <ability>` explains a class ability.', ['help kill', 'help eq', 'help fireball'], ['commands']],
  save: ['save', 'Saves your character right now (the game also saves automatically).', ['save'], ['quit']],
  quit: ['quit', 'Saves your character and leaves the game.', ['quit'], ['save']],
  mail: ['mail | mail <player> | mail read <n> | mail reply <n> = <text> | mail forward on', 'Mudmail: private mail to any player, even one who is offline. `mail` shows your inbox and opens the Mudmail window (read, reply and compose there). `mail <player>` opens the compose window; `mail send <player> <subject> = <message>` sends from the command line; `mail read <n>`, `mail reply <n> = <message>` and `mail delete <n|read|all>` work on the numbered list; `mail block <player>` stops someone writing to you. **Forwarding:** set your personal email (`email you@example.com`), type `mail forward on`, and a 6-digit code is emailed to you; confirm it with `mail verify <code>` and every new mudmail is also emailed to you (`mail forward off` stops it; changing your email turns it off until you confirm the new one). Finger shows when someone forwards their mudmail. At most 10 mudmails every 5 minutes; messages up to 2000 characters.', ['mail ben Hello = Want to team up?', 'mail read 1', 'mail reply 1 = Sure, noon at the Mirage Gate', 'mail forward on', 'mail verify 123456'], ['email', 'finger', 'idea']],
  elevator: ['elevator [floor]', 'Meridian Tower (in the Modern district, north of Commerce Avenue) has a basement and ten floors, each lobby with an elevator. `elevator` lists the floors with their monster levels and opens the elevator window; `elevator <floor>` goes straight there (B, 1 to 10, or `top`). The higher the floor, the tougher the monsters: the CEO and his three aggressive bodyguards wait on floor 10.', ['elevator', 'elevator 5', 'elevator top'], ['go', 'recall']],
  milestones: ['milestones', 'Lists the milestones of every area: which ones you have touched (a tick) and which you have not (a cross), their level ranges and where each one stands. You can only travel between milestones you have touched, and only from a milestone.', ['milestones'], ['milestone', 'touch', 'travel']],
  milestone: ['milestone | milestone <area>', 'Every area has a physical milestone (a standing stone). When you stand at one, `milestone` opens the travel window with a Travel button for each milestone you have touched, and `milestone <area>` travels there at once, for example `milestone dunes`. You MUST be standing at a milestone to travel, and the destination must be one you touched before. You cannot travel while fighting.', ['milestone', 'milestone forest'], ['touch', 'milestones', 'recall']],
  touch: ['touch <thing>', 'Touches an object in the room. Touching a milestone attunes you to its area, so you can travel there later from any other milestone. `look milestone` describes it.', ['touch milestone'], ['milestone', 'milestones']],
  builder: ['builder', 'Shows the link and private key of the grid area builder. Only for Architects and administrators. See `help builder` (the topic) for how to become an Architect and what you can build.', ['builder'], ['architect', 'admin']],
  admin: ['admin add <player> | admin remove <player> | admin list', 'Administrators only: makes another player an Administrator (a wizard, with all the wizard commands) or removes it. It works for players who are offline too. You cannot remove yourself, and there must always be at least one administrator.', ['admin add ben', 'admin list'], ['architect', 'builder']],
  architect: ['architect add <player> | architect remove <player> | architect list', 'Administrators only: makes a player an Architect, who may use the grid area builder (`builder`) to build areas, without any of the other wizard powers.', ['architect add ben'], ['admin', 'builder']],
  // wizard commands
  goto: ['goto <room id>', 'Wizards only: teleports you to a room, for example goto town/square.', ['goto modern/mme'], ['clone']],
  clone: ['clone <item id>', 'Wizards only: creates an item in your pack.', ['clone ironsword'], ['goto']],
  update: ['update', 'Wizards only: reloads the world data.', ['update'], ['shutdown']],
  shutdown: ['shutdown confirm | shutdown cancel', 'Wizards only: saves everyone and stops the server after a countdown.', ['shutdown confirm'], ['update']],
  events: ['events', 'Most holiday events run for 7 days around their dates (Talk Like a Pirate Day on Sept 19 and Pi Day on March 14 last the one day): Halloween (trick-or-treat), Thanksgiving (wild turkeys with a kill counter), Easter (bunnies with a kill counter and hidden eggs you can sell), Christmas (reindeer with a kill counter, Santa hats and ugly sweaters), New Year (party hats, champagne to drink, fireworks) the Fourth of July (fireworks), Talk Like a Pirate Day (everything you say comes out in pirate) and Pi Day (pies to find and eat). `events` shows the calendar, what is on and your counters. Administrators can force one for 7 days with `events start <name>` and end it with `events stop`.', ['events'], ['trickortreat', 'fireworks']],
  trickortreat: ['trickortreat  (also treat, trick)', 'During Halloween week: knock on a door in town for a treat (candy that heals, sometimes credits), a harmless trick, or, rarely, a costume piece (a witch hat or a jack-o\'-lantern helm). Every 30 seconds.', ['trickortreat', 'treat'], ['events']],
  fireworks: ['fireworks', 'Fills your screen (and the screens of everyone in the room) with fireworks for a few seconds. Switch the screen effects off in settings if you prefer. During New Year and the Fourth of July the whole world gets a show every 20 minutes.', ['fireworks'], ['events']],
  equip: ['equip [list]', 'Looks through your pack and bag and puts on the best weapon and armor for each slot (weapon by damage, armor by armor plus bonuses), using only what your level allows. `equip list` shows what it would change without doing it. Your old gear goes back to your pack; nothing is sold or dropped. Gear that needs a higher level is mentioned so you know what to look forward to.', ['equip', 'equip list'], ['wield', 'wear', 'inventory', 'bag']],
  launch: ['launch  (also fly)', 'In the cockpit of the starship Tharsis, flies it between Frostpeak Station and Mars (about 8 seconds). The Tharsis is docked at Frostpeak Station: go `in`, then north twice. Mars is for levels 30 and up. On Mars the ship waits at the Landing Pad (`in`); an empty ship flies itself home after a few minutes.', ['launch'], ['travel']],
  phone: ['phone <player> <message>  (also: tell)', 'Your 🍍Phone Pro Max is always with you (look in `inventory`): it is not in your bag, and cannot be dropped, sold, salvaged or given away. Text anyone who is online, wherever they are: `phone joe hello!` or `tell joe hello!`. For someone offline, use `mail`.', ['phone joe hello!', 'tell joe meet me at the square'], ['mail', 'gossip', 'say']],
  taxi: ['taxi [enter|out]  (also: enter taxi, ride)', 'The yellow Milestone Taxi tours every milestone in turn and waits 30 seconds at each stop. `enter taxi` at a stop (when you see it idling) costs 30 credits. Riding on to the next stop is free. Type `out` at a stop to step out, touch the milestone, then board again (another 30 credits) to continue. `taxi` shows where it is, how long until it leaves and the route.', ['taxi', 'enter taxi', 'taxi out'], ['milestones', 'touch']],
  farm: ['farm', 'Type `farm` in Ashfall Square to walk to Sunny Acres Farm. Four tradeskills live there: tilling, planting, milking and shearing (you pick them up the first time you use them). `till` the bare ground in a vegetable field, `plant <crop>` seeds (bought at the Farmer\'s Market), `harvest` when `plots` says RIPE, `milk cow` in the barn and `shear sheep` in the pastures. Sell it all to the old farmer for 90% of value. At level 20 in all four skills the farmer gives you denim overalls and a golden hoe (any level can use them). Killing the farmer, a cow or a sheep (they are level 50) bans you from the farm for an hour.', ['farm', 'till', 'plant carrot all', 'harvest', 'plots'], ['till', 'plant', 'harvest', 'milk', 'shear', 'tradeskills']],
  till: ['till [all]', 'Turn bare ground in a vegetable field at Sunny Acres Farm into a plot ready for seeds. `till all` does every plot. Raises Tilling; more skill gives you more plots (4, plus 1 for every 5 levels).', ['till', 'till all'], ['plant', 'harvest', 'farm']],
  plant: ['plant <crop> [all]', 'Sow seeds in your tilled plots. Crops: carrot, potato, lettuce, corn, tomato, pumpkin, strawberry and watermelon (higher planting levels unlock the better ones). `plant carrot all` fills every tilled plot. Seeds are sold at the Farmer\'s Market. Plots grow in real time, even while you are logged out.', ['plant carrot', 'plant potato all'], ['till', 'harvest', 'plots']],
  harvest: ['harvest', 'Collect every ripe crop from your plots (you must be in a vegetable field). The plots go back to bare ground, ready to be tilled again. Sell the crops to the old farmer at the Farmer\'s Market.', ['harvest'], ['plots', 'till', 'plant']],
  plots: ['plots', 'Shows your farm plots, what is growing in each, how long until it is ripe, your four farming skills and your progress toward the master farmer\'s reward.', ['plots'], ['till', 'plant', 'harvest']],
  milk: ['milk <cow>', 'Milk a dairy cow into your bucket (the Red Barn and the Cow Stalls at Sunny Acres Farm). Each cow gives milk about every half minute. Raises Milking. Sell the milk to the old farmer.', ['milk cow'], ['shear', 'farm']],
  shear: ['shear <sheep>', 'Shear a sheep for a fleece of wool (the two pastures at Sunny Acres Farm). Each sheep gives wool about every forty seconds. Raises Shearing. Sell the wool to the old farmer.', ['shear sheep'], ['milk', 'farm']],
  daily: ['daily', 'DAILY REWARDS: every time you log in at least 24 hours after your last reward, you are paid automatically, in experience and credits. Log in again within 48 hours to grow your streak: each consecutive day pays more (up to day 30), and every 7th day pays double. Miss a day and the streak starts over. `daily` shows your streak and the next rewards (and collects it if you have stayed logged in for 24 hours).', ['daily'], ['score', 'explore']],
  jukebox: ['jukebox', 'The saloons have no band: they have a JUKEBOX. `jukebox` (or tick Jukebox in the Windows menu) opens the Jukebox window anywhere, which plays a shared list of YouTube videos on shuffle for you. To add a song, stand at a jukebox in a saloon and type `jukebox add <youtube link>` (or paste it in the window); remove yours with `jukebox remove <number>`. You can have 6 songs in the list at a time.', ['jukebox', 'jukebox add https://www.youtube.com/watch?v=...', 'jukebox remove 2'], ['gossip']],
  wield: ['wield <weapon>, dual <weapon>, weaponskills', 'WEAPONS: every weapon belongs to a class (swords, clubs, blowguns, firearms, energy weapons, axes, unarmed, tridents, staves, spears, polearms, flails, bows, crossbows, explosives, hammers, maces, daggers, shuriken, slings, boomerangs, wands) and shields have a class of their own, and every one is ONE-HANDED or TWO-HANDED. A two-handed weapon leaves no hand for a shield or a second weapon. Wield a main weapon, then `dual <weapon>` for a one-handed second weapon in the off-hand: an extra attack every round (80% damage). Only Juggernauts and Titans can dual wield two-handed weapons. Each class has a WEAPON SKILL from 1 to 100 that rises as you hit with it: +0.6% damage per level (x1.59 at 100), kept through every remort. `weaponskills` lists them. Explosives sometimes get used up.', ['wield sword', 'dual dagger', 'weaponskills'], ['wear', 'inventory', 'task']],
  afflictions: ['bleeding, burning, poisoned, freezing, blinded, charmed, grappled, petrified', 'In combat, every landed blow (yours or a monster\'s) has a small chance to leave a NEGATIVE ENHANCEMENT: bleeding, burning and poisoned hurt every round; freezing and blinded ruin your aim (freezing can also cost a turn); charmed makes you lose your turn half the time; grappled stops you moving or fleeing; petrified freezes you for three rounds. Weapon classes favor some (daggers bleed, flails grapple, blowguns poison, energy burns and freezes), and monsters have their own (spiders poison, fire things burn, medusas petrify). They wear off in a few rounds and are cured by a level-up.', ['look'], ['wield', 'score']],
  relics: ['relics', 'Sometimes a BOSS drops a RELIC that lasts ONE HOUR: the Sword of Speed (double hits), the Ring of Invincibility (no damage taken), the Amulet of Strength (doubled strength), the Helmet of Intellect (doubled intelligence: double mana, spells hit 50% harder) and the Cloak of Regeneration (heals 50 hit points every round). Use it quickly: it crumbles to dust when the hour is up. Everyone hears when one is found.', ['wear ring', 'wield sword'], ['legends']],
  task: ['task [<stat>] [<amount>]', 'TASK POINTS: you earn one every 5 levels. `task` shows them; `task brawn` (or reflex, grit, mind, will, charm) spends one to raise that stat by 1 (up to +50 each). Unspent task points and everything you spent are kept through every remort. Existing characters were credited for levels already reached.', ['task', 'task brawn 3'], ['score', 'weaponskills']],
  tattoo: ['tattoo, brand, marks', 'Ink & Iron (off Market Row in Ashfall: type `ink`) will put a tattoo or a brand of your own description on your shoulder, back, leg or chest: `tattoo shoulder a coiled dragon`, `brand chest a lightning bolt`. One of each per place. Removal costs half as much again: `tattoo remove back`. Others see your markings when they `look` at you or `finger` you; `marks` lists yours.', ['ink', 'tattoo shoulder a coiled dragon', 'brand chest a lightning bolt', 'marks'], ['look', 'finger']],
  mount: ['mount, dismount', 'Buy a mount, then `mount` and `dismount`: a horse or donkey at the Livery Stable (Ashfall, `stable` at Market Row), a motorcycle at Rusty\'s Garage (modern, `garage` at the Auto Center), a hoverbike at the Hoverbike Depot (Mars, `depot`), a pterodactyl at the Primeval Roost (prehistoric, `roost`) and a great white shark at the Shark Pens (Poseidon\'s Realm, `pens`). A mount adds armor and attack and makes fleeing easier. Nobody rides indoors, land mounts cannot enter water, and a shark cannot leave it. A mount that you sell is gone.', ['stable', 'buy 2', 'mount', 'dismount'], ['wield', 'score']],
  idler: ['idler (a class)', 'The IDLER is a class for people who would rather not play: minimal stats, but every minute you spend idle (typing no commands) pays experience and credits, and the longer you stay idle the more each minute pays, up to 30x after 7 hours. Type any command and the clock starts over. `idle` shows your rate.', ['idle'], ['classes']],
  search: ['search', 'SEARCH the room for a hidden treasure or a trap: a small chance of a secret cache (credits and sometimes an item, a better chance for Thieves) and a smaller chance of a trap (spikes, poison darts, flame, a snare or gas). A quick Reflex check, or a Thief, can disarm it. You can search a room once every five minutes, and once every 15 seconds overall. Safe rooms rarely hide anything, and never traps.', ['search'], ['look', 'tradeskills']],
  numbers: ['look teller 2', 'When a room has several of the same thing (two bank tellers, two swords on the floor), a name picks the first one, and a name with a number picks that one: `look teller 2` is the second teller, `kill rat 3` attacks the third rat, `get sword 2`, `talk teller 2`. The form `2.teller` works too. This works for monsters, people, items and things you carry.', ['look teller 2', 'kill rat 3', 'get sword 2'], ['look', 'kill', 'get']],
  gates: ['the realms (Ashfall Square)', 'The lands are separate: no area connects to another. Ashfall Square has five great gates, one for each realm: `oldwest`, `fantasy`, `future`, `modern` and `prehistoric` (and `farm` for Sunny Acres, `d` for Buckstars). Each gate opens onto ONE big grid map that flows from land to land: for example the fantasy realm runs from Blimble Hollow through the forest, crypt, marsh and on to Atlantis, Hades and the castle in the clouds, joined end to end by short trails. The map shows where you are, and the area name (top of the map) tells you which land you are in. `out` from the first room leads back to the Square, and `recall` always returns you there.', ['fantasy', 'out', 'recall'], ['recall', 'map']],
  bot: ['bot [on|off|<message>]', 'The resident bots (Zeph, Rook, Mira, Dusty, Kaz and Lyra) chat on their own channel, `bot`, instead of gossip. `bot off` mutes it, `bot on` brings it back, and `bot <message>` talks to them (they answer).', ['bot off', 'bot hello'], ['gossip']],
  auto: ['auto [<name> on|off]', 'Lists every automatic setting, mute and gag in one place: autoheal, autoflee, autokill, bag auto loot, anyquest, brief, the combat gag, gossip, the bot channel, login notices and every mute type (bounty, levels, quests, taunts, deaths, weather). Change one with `auto heal off`, `auto flee on`, `auto kill on`, `auto loot on|off`, `auto gag on`, and so on.', ['auto', 'auto heal off'], ['autoheal', 'mute', 'gag', 'bag']],
  emojis: ['emojis', 'The emojis button on the button bar opens a picker (faces, hands, hearts, fantasy, animals, food, fun, signs): click one to add it to what you are typing, then use gossip, say or tell. Shortcodes work too: `:skull:`, `:fire:`, `:heart:`, `:thumbsup:`, `:dragon:`, `:beer:` and about 80 more become emoji in gossip, say, tell and the bot channel.', ['gossip :fire: on my way :thumbsup:'], ['gossip', 'say', 'tell']],
  idlemaster: ['idle master (a remort class)', 'An Idler who remorts becomes an IDLE MASTER: every remort level adds +25% to idle experience and credits (an Idler can remort all the way to Remort 200 as an Idle Master, for up to x51 idle pay), on top of the bonus for idling longer. Only Idlers and Idle Masters can choose the class.', ['remort idlemaster', 'idle'], ['idler', 'remort']],
  mythic: ['Olympus, Asgard, the Otherworld and Camelot', 'Four mythic lands at the far end of the fantasy realm: Avalon and Camelot (levels 66-78, King Arthur, Merlin, Mordred, Stonehenge), the Otherworld (70-84, the Tuatha De Danann, the Fae, giants, leprechauns, pixies; the Dagda), Mount Olympus (86-100, the Greek gods and Cronus; Zeus) and Asgard (88-100, the Norse gods; Odin). The great heroes of each give quests, and two shared quests tie all four lands together: Merlin\'s The Convergence of Legends and Odysseus\'s The Four Kings.', ['fantasy'], ['gates', 'quests']],
  vow: ['vow [<goddess>|lore <goddess>|forsake]', 'Four goddesses hear vows. SERAPHINA, Goddess of Good (healing, justice, protection, light; symbol: a golden sun): compassionate but unwavering against evil; blessing +6% maximum health. ELYNDRA, Goddess of Neutrality (balance, fate, nature, equilibrium; symbol: silver scales): neither good nor evil, she preserves the balance of existence; blessing +2 luck and better defense as you level. MORGATH, Goddess of Evil (destruction, domination, corruption, darkness; symbol: a black skull crowned in flame): ruthless, manipulative and hungry for power; blessing +6% damage. LAGATHA, Goddess of Lag (lag, latency, disconnections, freezes; symbol: a glitched hourglass): unpredictable and mischievous, she strikes without warning; blessing: each landed blow has a 5% chance to freeze your enemy for three rounds. `vow` lists them with their portraits, `vow seraphina` swears (the first vow is free; changing it costs credits), `vow lore morgath` shows one goddess. Your goddess shows in `finger` and `score`.', ['vow', 'vow lore lagatha', 'vow seraphina'], ['finger', 'score', 'alignment']],
  deities: ['deities (the four goddesses)', 'See `vow`: Seraphina (Good), Elyndra (Neutrality), Morgath (Evil) and Lagatha (Lag).', ['vow'], ['vow']],
  bounty: ['bounty rewards', 'Every ten bounty points you earn (in `bounty`/`score`) pays out: +10 bag of holding slots, +2 levels in every tradeskill, +2 levels in every weapon skill and +1 task point. Characters who already had bounty points were paid for them the next time they logged in.', ['score', 'weaponskills', 'task'], ['bounty', 'task']],
  finger: ['finger [<name>]', 'Shows a clean two-column sheet for any player or bot: name, class, gender, level, deity, leaderboard rank, age (years, weeks, days, hours), best kill, best team kill, arch foe (the last monster that killed them), when they came on, how long they have been idle, and their mail (forwarding and unread/read counts), plus any tattoos and brands.', ['finger Grog', 'finger'], ['score', 'vow', 'age']],
  follow: ['follow, assist, summonbot', '`follow <name>` makes you follow a player (or bot) automatically: when they leave the room, you go with them (`follow off` stops). `assist [<name>]` joins a fight a teammate is already in. `summonbot [<name>]` (also `callbot`) calls a resident bot to team with you: it arrives where you are, joins your team, follows you and assists in combat; `dismissbot` sends it back to the Proving Grounds. One bot at a time, the bot only answers to the player who summoned it, and a team shares XP and credits as usual.', ['summonbot kaz', 'follow kaz', 'assist', 'dismissbot'], ['team', 'tc']],
  remort200: ['remorting to level 200', 'You can remort 200 times. Every remort gives +4% health and mana and +3% spell power (+2% and +1.5% from Remort 41 on), +1 attack and defense die every 4 remorts (every 8 after 40), levelling gets 10% slower (4% after Remort 40), and EVERY remort level unlocks a stronger ability (200 in all). Titans gain more attacks at Remort 50 (7), 100 (8), 150 (9) and 200 (10). The level cap is 200 and you remort at level 200: remort levels are the power that carries you through the endgame areas (the future realm at 185 to 200, Sol and Mercury, Perdition Gulch).', ['remort'], ['remort', 'classes']],
  sol: ['Sol and Mercury', 'At the far end of the future realm: 150 rooms (levels 150 to 200) on Mercury, where iron-based life has forge-cities and fights the creatures of the sun, and on Sol itself, with Ferrum Prime (level 190), Helia the Oracle (195) and Sol Invictus the Living Star (level 200) as bosses. Level 150 to 200: only the strongest heroes survive. Dr. Voss and Aten the Envoy give 11 quests.', ['future'], ['mythic', 'remort200']],
  pizza: ['Pizza Palace', 'In the modern realm (`modern` at Ashfall Square, after the cinema): a full pizza restaurant. At the Order Counter and the Soda Fountain you can `buy` pizzas, sodas and sides (they restore health and mana). Quest from Chef Luigi: buy dough, sauce and mozzarella at the Walk-in Pantry, `make pizza` at the Prep Station, `bake` it in the Brick Oven Room (15 seconds), and `deliver` it to Hungry Harold at 42 Elm Street.', ['make pizza', 'bake', 'deliver'], ['quests']],
  jungle: ['The Megalithic Jungle', 'At the far end of the prehistoric realm: 50 rooms (levels 40 to 55) of jungle and giant standing stones, full of prehistoric creatures, with the Tyrannosaurus Imperator as boss. Shaman Oog at the gate has six quests.', ['prehistoric'], ['pizza']],
  blessing: ['goddess blessing', 'Now and then a goddess (Seraphina, Elyndra, Morgath or Lagatha) picks a random player online and blesses them with +40% experience for one hour. It shows as an enhancement bar and is announced in the gossip channel. `bless` shows how long yours has left.', ['bless', 'vow'], ['vow']],
  futurelevels: ['future realm levels', 'Every area of the future realm (Starship Aurora, Frostpeak Station, Ember Wastes, Mars, the Abyss, Exterminus and Pluto) is now at levels 185 to 200, and Sol and Mercury runs from 150 to 200: this is the challenge for high-remort heroes. The Proving Grounds keep their own levels.', ['future'], ['remort200', 'sol']],
  homestead: ['the homestead: build your own home', 'East of Sunny Acres Farm lies the Homestead: 54 rooms, 51 of them numbered plots of land. Stand on a plot and `claim land` (your first plot costs 10,000 credits, the second 50,000, the third 250,000): the whole room is yours. Chop its trees (`chop`), saw logs into planks and beams (`saw`), and buy nails, bricks, stone, concrete mix, sand, buckets, glass, iron bars, roof tiles, rope, thatch, paint, locks, banners and saplings at the Lumber and Supply Yard. Concrete: `fill bucket` at the well, `mix`, `form` (a wooden form, once), `pour`: a slab after curing. Then `build hut`, and later cabin, house, keep, compound, castle and fortress, in that order; each takes more materials, credits and time (a hut a minute, a fortress an hour; you can log out while it builds). Inside your dwelling, `build room <direction> <name>` adds rooms (a cabin holds 3, a house 6, a keep 10, a compound 16, a castle 25, a fortress 40), `roomname` and `roomdesc` describe them, `furnish` places beds, tables, fireplaces, thrones and more. `home` shows your plan and what is missing, `home access open|private`, `home invite <name>`, `home name <text>`; `homes` lists the neighbors; `plant sapling` grows two more trees; `abandon land confirm` gives a plot up.', ['claim land', 'chop', 'saw', 'mix', 'build hut', 'home'], ['chop', 'furnish']],
  furnish: ['furnish, roomname, roomdesc', 'Inside your own dwelling: `furnish` lists furniture and what it needs (bed, table, chairs, bookshelf, fireplace, rug, chest, trophy case, throne, armor stand, weapon rack, banner, fountain, flower garden, paint mural; 10 pieces per room), `furnish <name>` places one, `unfurnish <name>` removes it. `roomname <text>` and `roomdesc <text>` rename and describe the room you are standing in.', ['furnish bed', 'roomname The Great Hall'], ['homestead']],
  chop: ['chop (woodcutting)', 'The Woodcutting tradeskill (learned the first time you `chop`): chop trees on the Homestead (and the plots you own) for logs, three or more per chop. `saw plank` and `saw beam` turn logs into building materials.', ['chop', 'saw'], ['homestead']],
  perdition: ['Perdition Gulch', 'The Old West endgame: 50 rooms (levels 195 to 200) past the end of the Old West trail: Boot Hill, the Dead Rock ghost town, the phantom railroad and Devil\'s Canyon, with Dead-Eye Dan (196), the Wendigo King (198) and Marshal Abaddon (200) as bosses. Sheriff Silas Crane at the gate gives 8 quests.', ['oldwest'], ['remort200']],
  combatview: ['the combat view: classic or enhanced', 'While you fight, a combat pop-up shows both fighters. The Classic view (the default) shows a framed portrait on each side; the Enhanced view draws two full fighters that lunge and swing weapons, with sparks, slash marks and a screen shake on critical hits. Click Classic/Enhanced in the combat window, or pick the style in Settings.', ['settings'], ['settings']],
  daynight: ['day and night', 'A game day lasts 48 real minutes (the clock at the top right). It gets a little darker as the day goes on: brightest at 1 pm, dusk from about 5 pm, and night from 9 pm to 5 am. At night, outdoors, you need a light: spellcasters (Magician, Cleric, Druid, Alchemist, Necromancer, Bard, Wirewalker, Engineer, Dragon) have the `light` spell (it costs mana and lasts 15 minutes), and everyone can `make torch` (20 minutes). Without a light you cannot see the room (only the exits) and you fight at -30%. Towns, buildings, safe rooms and camps are lit.', ['light', 'make torch'], ['spells', 'score']],
  torch: ['make torch', '`make torch` makes and lights a torch that burns for 20 minutes (stacking up to an hour). Spellcasters can cast `light` instead. `light` casts the spell, or makes a torch if you have no spell.', ['make torch', 'light'], ['daynight']],
  scars: ['scars', 'Every death leaves a new scar on a random part of your body (a bite from a wolf, a burn from a demon, a bullet from an outlaw...). Others see them when they look at you and in `finger`; `scars` lists yours. They never fade.', ['scars'], ['finger']],
  reputation: ['reputation', 'Every quest you complete earns reputation in the area where its quest giver lives (1 point, 3 for a boss quest, +1 for a quest at level 100 or above). Reputation pays: +1% credits from kills per point (max +50%), +1% when you sell (max +50%), and 0.5% off in shops (max 30%). Your reputation in the area you are standing in counts in full; elsewhere it counts a quarter. `reputation` shows yours; it is also in `score` and the leaderboard. Titles: Stranger, Known, Respected, Trusted, Honored, Revered, Legendary, Mythic.', ['reputation', 'score'], ['quests', 'leaderboard']],
  bodyguard: ['bodyguards', 'The Ironside Bodyguard Agency (off the streets of Ashfall) rents a bodyguard for one hour: `hire bodyguard` costs 600 credits per level (at least 1,000). He is half your level, follows you and strikes your enemy every round. While he is on the job you earn 10% less experience and credits. `bodyguard` shows the time left; `dismiss bodyguard` sends him away (no refund).', ['hire bodyguard', 'bodyguard', 'dismiss bodyguard'], ['summonbot']],
  worldmap: ['the world map', '`worldmap` (or the World Map button at the top right) opens the whole world on one page: every room, region by region, coloured by area, with safe rooms, shops and bosses marked and your position pulsing. Rooms you have not explored are dimmed (or hidden with the checkbox). Hover a room for its name. It shows how many rooms there are in all and how many you have explored. The Player Guide has the same map.', ['worldmap'], ['explore']],
  volcano: ['Mount Cinderfang', 'A living volcano at the edge of the prehistoric lands: 60 rooms at levels 120-140, from the ash-forest to the lava-filled caldera. Fire salamanders, cinder hounds, lava worms, obsidian golems, magma drakes and flame elementals, and two bosses: Cinderfang the Lava Wyrm and Ignis, the Caldera Giant. Kaldra the Ashspeaker (the fire camp at the gate) gives 6 quests.'],
  ironage: ["The Ore-Kings' Reach", 'Where stone gave way to metal: 50 rooms at levels 62-80, from Bronze Age hill-forts and tin roads to Iron Age war-camps and slag-fields. Brask, the Bronze King, and Dagan Ironhand, the Iron Lord, are fighting over the tin and the iron. Hild the Smith-Mother (the forge-gate) gives 5 quests.'],
  void: ['The Void', 'The darkest place in the Future realm: 100 rooms whose descriptions are written in dark gray. To cross the threshold your level plus your remorts must reach 250 (level 200 and Remort 50). Every monster is a hard "void", and Nihil, the Void Sovereign, waits at the end. The moment you step past the Warden\'s Threshold an automatic contract starts: kill every void within 30 minutes (reminders at 20, 10, 5 and 1 minute) for a huge reward, or the Void forgets you and you can try again.'],
  poweramor: ['Power Armor', 'A body-slot suit built for Titans. It is loaded into a Titan\'s pack automatically at Remort 20 (and for Titans already past it, at their next login). `wear power armor`. Any remorted player can wear any level of equipment, and the suit adds a great deal of health, damage and attack dice.'],
  extinction: ['The Extinction Event', 'The toughest area in the game: 60 rooms at level 200 at the far end of the prehistoric realm (the realm with the fewest areas): the burning crater of the meteor that ended the dinosaurs. Every monster is level 200 and built tough; bosses are the Meteor Titan, Apex Tyrannus (the first rex) and Chronophage, Devourer of Ages. Chrona the Timekeeper at the gate gives 8 quests.', ['prehistoric'], ['perdition']],
  alignment: ['alignment [good|neutral|evil]', 'Choose your alignment, once an hour. GOOD gives +5% maximum health, NEUTRAL (the default) +5% experience from everything, EVIL +5% damage in combat. It shows in `score`, `finger`, `who` and on the website.', ['alignment', 'alignment good'], ['score', 'finger', 'who']],
  scavenge: ['scavenge  (a tradeskill)', 'Scavenging: learn it (`learn scavenging`), then `scavenge` in a room with salvageable wreckage ("wreck" in the Resources line): Exterminus, Mars, Pluto and the Aurora. You find scrap metal, copper wire, circuit boards and power cells, and from level 20 the impossible metal UNOBTAINIUM, which exists only in the futuristic worlds. Exterminators drop it too.', ['learn scavenging', 'scavenge'], ['unobtainium', 'augment', 'tradeskills']],
  unobtainium: ['unobtainium', 'The impossible metal of the futuristic worlds. Scavenge it (level 20+) from wreckage on Exterminus, Mars, Pluto and the Aurora, or take it from an Exterminator robot. Ripperdocs use it to BUILD unobtainium implants (`list`, `install`: credits plus unobtainium) and to UPGRADE any implant you have with `augment` (up to 5 times, +20% of its bonus each).', ['list', 'install 1', 'augment'], ['scavenge', 'augment', 'cyber']],
  augment: ['augment [<implant>]', 'At a ripperdoc, upgrade an implant you have installed with unobtainium and credits. Each of up to five upgrades adds 20% of the implant bonus. `augment` alone lists your implants and what the next upgrade costs.', ['augment', 'augment 1'], ['unobtainium', 'cyber', 'install']],
  watch: ['watch, movies', 'At Multiverse Cinema 12 (Modern Gate at Ashfall Square: `modern`, then `cinema`): `movies` lists what is showing, buy a ticket at the box office, take a seat in an auditorium and `watch`. A fake movie plays scene by scene and you leave rested (+25% health and mana).', ['movies', 'watch'], ['bracelet']],
  magazine: ['magazine', 'The Multiverse Magazine is on the rack in Ashfall Square: `get magazine` (or `get mag`, or `get magazine from rack`), then `read magazine`. A new issue is published every 30 minutes with contracts completed, new faces and logins, level-ups, obituaries and the tradeskill masters (level over 25).', ['get magazine', 'read magazine'], ['who', 'leaderboard']],
  linkdead: ['linkdead', 'If your connection drops, your character stays in the world, linkdead, for 5 minutes (monsters can still hurt you), and shows as linkdead in `who` and on the website. Log back in to take over where you were. `quit` leaves at once. Socials work remotely: `smile Bob` from anywhere sends them "from afar".', ['who'], ['who', 'quit']],
  explore: ['explore  (also: explored)', 'Shows your exploration points: you earn 1 point for every new room you enter, out of every room in the multiverse, with a breakdown by area and a message at 10, 25, 50, 100 rooms and beyond. Exploration points are in `score` and count toward the leaderboard (x5 each).', ['explore'], ['score', 'leaderboard', 'age']],
  age: ['age  (also: played)', 'Shows how old your character is (real time since creation), your total time logged in (counted live, saved with your character) and this session. The same numbers appear in `score` and `finger`.', ['age', 'played'], ['score', 'finger', 'explore']],
  wrist: ['the wrist slot: bracelets and watches', 'The wrist slot holds a wristband, bracelet, bangle or watch. See `bracelet`.', ['wear wristband'], ['bracelet', 'time']],
  slots: ['equipment slots', 'Weapon, off-hand weapon, head, FACE (sunglasses, visors, glasses, masks, goggles, monocles, bandanas, balaclavas), neck, body, HANDS (gloves, gauntlets, bracers), shield, WRIST (bracelets and watches), ring, cloak, belt, LEGS (leggings, pants, breeches) and feet. `wear <item>` puts armor in its slot; `inventory` shows every slot.', ['inventory', 'wear gloves'], ['wear', 'inventory']],
  bracelet: ['bracelets and watches', 'The wrist slot (called bracelet in older versions) holds a wristband, bracelet, bangle or watch: shops in Ashfall, the modern district, the Dune Bazaar, the Pixie Market, the Pearl Market, the Manor, Mars, the Sea, Hades and Pluto all sell them. `wear` one like any armor. A watch or wrist communicator also makes `time` show the exact time.', ['wear bracelet', 'time'], ['wear', 'equipment', 'inventory']],
  time: ['time', 'Tells you the time. Without a watch you get a guess by the sun; wearing a watch or wrist communicator in the wrist slot gives the exact time.', ['time'], ['bracelet']],
  anyquest: ['anyquest [on|off]', 'When on, you can accept quests whatever your level (quests that need an earlier quest still need it). The quest pop-up and `accept` then treat every quest as available. Also a checkbox in settings. Saved with your character.', ['anyquest', 'anyquest off'], ['quests', 'board', 'accept']],
  uptime: ['uptime', 'Shows how long the game server has been online since it last started (also shown next to the Windows button, top right of the screen).', ['uptime'], ['who', 'score']],
  prime: ['prime', 'PRIME is a permanent gift once you reach Remort 1 (it stays with you forever). You can type `prime`: for ONE HOUR you get +50% health, mana and luck (all refilled), +50% spell power and half-price spells. After it expires there is one hour of downtime before it is ready again. The PRIME bar under your vitals shows the countdown: while it burns it counts down the buff, and afterwards it fills until PRIME is READY again (click the bar to use it).', ['prime'], ['remort', 'spells']],
  peace: ['peace', 'Staff only (administrators, architects and builders): stops every fight in the room at once, and for two minutes not even a boss will start a new one. Handy for rescuing a player or testing an area.', ['peace'], ['admin', 'architect']],
  bones: ['bones <bet> <call>  (also: dice)', 'Rolling Bones, a solo dice game played in the saloons. Bet 10 to 1,000 credits and call the roll of two dice: `low` (2 to 6) and `high` (8 to 12) pay 1.25 to 1, `seven` and `doubles` pay 4.5 to 1, `snake` (1+1) and `boxcars` (6+6) pay 30 to 1. A win returns your bet plus the winnings. `bones` alone lists the calls; `look dice` at a saloon shows the table sign.', ['bones 100 high', 'bones 50 seven', 'dice 25 boxcars'], ['blackjack']],
  value: ['value <item>', 'Tells you what a shop would pay for something you carry (pack, worn or bag), including any upgrades you paid for, anywhere in the world. Legendary items show their auction worth instead, and materials show the Salvage Exchange price too.', ['value oathblade', 'value ore'], ['sell', 'rsell', 'list']],
  give: ['give <amount> <player>', 'Hands credits to another player in the same room. Also written `give 50 credits ben` or `pay ben 50`. The amount leaves your purse and goes to theirs at once, and nothing can undo it, so make sure it is the right person.', ['give 50 ben', 'give 200 credits ben'], ['trade', 'who']],
  changeclass: ['changeclass [confirm <class>]', 'Only in the Hall of Many Faces (north of the Adventurers\' Guild; `travel faces`). Lists the classes you can change into and the price, which grows with your level (500 + 250 per level, double for remort characters, who can only swap between remort classes). `changeclass <class>` previews it, `changeclass confirm <class>` pays. Changing is FREE for characters below level 5. Your level, gear and credits stay; your abilities change. Changing gender is always free (`gender male|female|other`).', ['changeclass', 'changeclass necromancer', 'changeclass confirm necromancer'], ['gender', 'remort', 'class']],
  deleteme: ['deleteme [confirm]', 'Permanently deletes YOUR character: level, gear, credits, quests, mudmail and settings, all of it. Type `deleteme` to read the warning, then `deleteme confirm` within two minutes. Nobody can restore a deleted character. You may then log in again with the same name and password to create a brand new character from scratch. (The only Administrator cannot delete themselves: make someone else an Administrator first.)', ['deleteme', 'deleteme confirm'], ['suicide', 'quit']],
  suicide: ['suicide  (support and crisis lines)', 'If you are thinking about suicide or hurting yourself, please reach out to someone right now. You do not have to be sure, and you do not have to be in a crisis to call. Trained, caring people answer these lines, free, and many are open 24 hours a day. If you are in immediate danger, call your local emergency number: 911 (United States, Canada), 999 or 112 (United Kingdom, Ireland), 000 (Australia), 111 (New Zealand).\nUNITED STATES: 988 Suicide and Crisis Lifeline. Call or text 988, or chat at 988lifeline.org. Veterans can press 1. Crisis Text Line: text HOME to 741741.\nCANADA: Call or text 9-8-8 (Suicide Crisis Helpline), any time, in English or French.\nUNITED KINGDOM: Samaritans, call 116 123 (free, 24 hours). You can also text SHOUT to 85258.\nIRELAND: Samaritans, call 116 123 (free, 24 hours). Pieta: 1800 247 247.\nAUSTRALIA: Lifeline, call 13 11 14 (24 hours) or text 0477 13 11 14. Suicide Call Back Service: 1300 659 467.\nNEW ZEALAND: Call or text 1737 (free, 24 hours) to talk to a trained counsellor.\nSOUTH AFRICA: SADAG suicide crisis line, 0800 567 567.\nELSEWHERE: findahelpline.com lists free, confidential lines by country, and befrienders.org has centers around the world.\nIf the person you are worried about is someone else, stay with them, ask them directly, and help them contact one of these lines or emergency services. You matter, and so do they.\nIf you are here because you want to delete your character, that is a different thing and easy to do: type `help deleteme`.', ['suicide'], ['deleteme']],
  purge: ['purge <player>', 'Administrators only: permanently deletes a player\'s character, online or not, including their mudmail. They can register the name again from scratch. Administrators must have their role removed first (`admin remove <player>`), and you cannot purge yourself (use `deleteme`).', ['purge Troublemaker'], ['ban', 'silence', 'admin']],
  ban: ['ban <player|ip>', 'Administrators only: bans an IP address from logging in. Give a player\'s name (the address they last logged in from is used) or an address directly. Everyone connected from it is disconnected at once. Addresses of the local machine and of Administrators cannot be banned. See `bans` and `unban`. Behind a reverse proxy, start the server with TRUST_PROXY=1 so real visitor addresses are used.', ['ban Troublemaker', 'ban 203.0.113.9'], ['unban', 'bans', 'purge']],
  unban: ['unban <ip|player>', 'Administrators only: lifts a ban on an address (or on the last address a player used).', ['unban 203.0.113.9'], ['ban', 'bans']],
  bans: ['bans', 'Administrators only: lists banned addresses, who banned them and when.', ['bans'], ['ban', 'unban']],
  silence: ['silence <player>', 'Administrators only: for 10 minutes the player cannot send tells, gossips or shouts (they can still play, fight and read). Administrators and bots cannot be silenced. It ends by itself, or with `unsilence`.', ['silence Troublemaker'], ['unsilence', 'purge', 'ban']],
  unsilence: ['unsilence <player>', 'Administrators only: lets a silenced player speak again.', ['unsilence Troublemaker'], ['silence']],
  tweet: ['tweet [test]', 'Administrators only: shows the X/Twitter posting status; `tweet test` posts a test message. Twitter keys are not required: the game works without them.', ['tweet', 'tweet test'], ['discord', 'github']],
  discord: ['discord', 'Wizards only: shows the Discord link status.', ['discord'], ['github', 'twitter']],
  github: ['github', 'Wizards only: shows the GitHub sync status.', ['github'], ['discord', 'twitter']],
  twitter: ['twitter', 'Wizards only: shows the X/Twitter posting status.', ['twitter'], ['discord', 'github']],
};
const WIZ = new Set(['tweet', 'purge', 'ban', 'unban', 'bans', 'silence', 'unsilence', 'goto', 'clone', 'update', 'shutdown', 'discord', 'github', 'twitter', 'admin', 'architect']);

// Help topics: `help <topic>` (checked before commands). Each entry: [title, [paragraphs], see also]
const BUILD = ['Becoming an Architect (builder, wizard, god)', [
  'There are three ranks. A PLAYER explores and fights. An ARCHITECT (also called a Builder) can build: new areas, rooms, monsters, items, shops. An ADMINISTRATOR (also called a Wizard or God) runs the game: everything an Architect can do, plus the wizard commands (goto, clone, update, shutdown, weather control) and the power to make other Architects and Administrators. Administrators show as (Administrator) in the who list, Architects as (Architect).',
  'WHAT YOU CAN BUILD: any area is open for discussion. A new realm in any theme (Old West, fantasy, sci-fi, modern, prehistoric, horror, something nobody has tried), a new wing for an existing area, a town, a dungeon, a ship. You decide the story, the level range, the monsters and the boss, how it connects to the rest of the world, and what it gives the players.',
  'THE GUI BUILDER makes it easy: nothing to code. You paint rooms on a grid, link them (auto-link or the link tool), write descriptions, set flags (safe, camp, inn, healer, forge), place monsters and items, set up shops and gathering nodes (herbs, ore, fish), add up and down links, connect your area to existing rooms, and create new monsters. Press Save and your area goes live at once, no restart; the server backs it up and it appears on the map. Every area also gets a milestone automatically.',
  'HOW TO BECOME AN ARCHITECT: 1) Write down your idea: the theme, the level range, a few rooms, the boss, and how players get there. 2) Send it to an Administrator with `idea <your area idea>` (it is filed for the developer on GitHub) or with `mail <administrator> <subject> = <message>`; `who` shows who the Administrators are. 3) Talk it over: the Administrator may ask for changes, suggest where it should connect, or help with balance. 4) When you are approved the Administrator types `architect add <you>`. 5) Type `builder` to get the builder link and your key, open it in your browser and start painting.',
  'TIPS: keep exits two-way and every room reachable; put a safe room with a camp near the entrance; match monster levels to your level range and give your boss something worth killing; short, vivid descriptions (about 20 to 30 words) read best in the game; test by walking your area before you announce it.',
], ['idea', 'mail', 'builder', 'admin', 'architect']];
const T = {
  implant: ['Implants (cyberware)', ['Implants (cyberware, chrome) are permanent upgrades for your body: more hit points, more attack and defense, better loot and so on. You buy and fit them at a ripperdoc: the Chrome Clinic and the Neural Implant Lab in Ashfall (west of the saloon).', 'HOW TO BUY AND INSTALL ONE: 1) walk into the clinic or the lab. 2) Type `list` to see every implant for sale: its name, price in credits, how much aura it uses, what it gives you and the level you need. 3) Type `install <name>` with the full name, for example `install brawn implant mk i`. The surgery is paid for at once (the price in the list) and the implant works immediately.', 'AURA: you have 6.0 aura and every implant uses some of it, so you can only fit so much chrome. Less aura also shrinks your mana pool (see `help aura`). If an implant needs more aura than you have left, uninstall something first.', 'UPGRADES: many implants come in Marks (Mk I, Mk II, Mk III...). Install them in order. Fitting the next Mark trades in the old one for half its price back.', 'OTHER COMMANDS: `cyber` shows what you have installed and your aura. `uninstall <name>` (at a clinic) removes one and pays you half its price. Level limits apply: the list shows the level each implant needs. There is also a sign on the wall of the Neural Implant Lab: `read sign`.'], ['cyber', 'install', 'uninstall', 'list', 'aura']],
  implants: ['Implants (cyberware)', ['Implants (cyberware, chrome) are permanent upgrades for your body: more hit points, more attack and defense, better loot and so on. You buy and fit them at a ripperdoc: the Chrome Clinic and the Neural Implant Lab in Ashfall (west of the saloon).', 'HOW TO BUY AND INSTALL ONE: 1) walk into the clinic or the lab. 2) Type `list` to see every implant for sale: its name, price in credits, how much aura it uses, what it gives you and the level you need. 3) Type `install <name>` with the full name, for example `install brawn implant mk i`. The surgery is paid for at once (the price in the list) and the implant works immediately.', 'AURA: you have 6.0 aura and every implant uses some of it, so you can only fit so much chrome. Less aura also shrinks your mana pool (see `help aura`). If an implant needs more aura than you have left, uninstall something first.', 'UPGRADES: many implants come in Marks (Mk I, Mk II, Mk III...). Install them in order. Fitting the next Mark trades in the old one for half its price back.', 'OTHER COMMANDS: `cyber` shows what you have installed and your aura. `uninstall <name>` (at a clinic) removes one and pays you half its price. Level limits apply: the list shows the level each implant needs. There is also a sign on the wall of the Neural Implant Lab: `read sign`.'], ['cyber', 'install', 'uninstall', 'list', 'aura']],
  aura: ['Aura', [
    'GROWING AURA: your maximum aura starts at 6.0, grows a little with every level (+0.03 per level) and every remort adds a full extra aura point. Extra aura pays for more chrome, and your mana is only reduced when your aura drops below 6.',
    'Aura is the spiritual room inside you that your magic runs on. Everyone starts with 6.0 aura, and you can see it in the Character panel on the left, in `score` and in `cyber`.',
    'WHAT IT DOES: your aura sets how much mana you can hold. Your maximum mana is multiplied by your aura divided by 6, so at 6.0 you have all of it, at 3.0 half of it, and it never drops below 15%. Magic users therefore want to keep their aura high.',
    'WHAT IT IS FOR: chrome (cyberware) costs aura. Every implant you install at a clinic or implant lab takes a slice of aura (the price list shows each one), and you cannot install an implant if you do not have enough aura left. That is the trade-off: implants give you hard bonuses (hit points, reflexes, willpower and more) but thin out the aura your spells need. Uninstalling an implant gives its aura back (and pays half its price).',
    'IN SHORT: lots of chrome means a tough body and less mana; no chrome means full mana and a more fragile body. Plan your implants around your class.',
  ], ['cyber', 'install', 'uninstall', 'score', 'class']],
  wizard: BUILD, builder: BUILD, god: BUILD, architect: BUILD, admin: BUILD, administrator: BUILD,
};
module.exports = { H, WIZ, T };
